"""Shared helpers for kernel dispatch and fallbacks."""


import logging
import os
import threading
from typing import Any, Callable, Iterable, TypeVar
import warnings

log = logging.getLogger(__name__)

import torch

from kestrel_kernels.arch import get_cuda_compute_capability


_FALLBACK_WARNED: set[str] = set()
_FALLBACK_WARN_LOCK = threading.Lock()
_T = TypeVar("_T")


def ceil_div(n: int, d: int) -> int:
    """Ceiling division for non-negative ints: ceil_div(7, 2) == 4."""
    return (n + d - 1) // d


def flatten_rows_view(tensor: torch.Tensor) -> torch.Tensor:
    """View ``[..., width]`` as rows without copying.

    Singleton dimensions carry no address movement, so their strides are not
    layout constraints. This matters for views such as ``[1, tokens, width]``
    whose outer singleton keeps a padded parent stride even though the token
    rows themselves are contiguous. Non-singleton dimensions must still form
    one regular row domain; otherwise a two-dimensional ``as_strided`` view
    would change the element ordering.
    """
    if tensor.ndim == 0:
        raise ValueError("tensor must have at least one dimension")
    if tensor.stride(-1) != 1:
        raise ValueError("last dimension must have unit stride")
    if tensor.ndim == 1:
        return tensor.view(1, tensor.shape[0])
    if tensor.ndim == 2:
        return tensor

    leading_dims = [dim for dim in range(tensor.ndim - 1) if tensor.shape[dim] > 1]
    if not leading_dims:
        row_stride = int(tensor.shape[-1])
    else:
        row_stride = int(tensor.stride(leading_dims[-1]))
        inner_rows = int(tensor.shape[leading_dims[-1]])
        for dim in reversed(leading_dims[:-1]):
            if int(tensor.stride(dim)) != inner_rows * row_stride:
                raise ValueError("leading dimensions are not flattenable without a copy")
            inner_rows *= int(tensor.shape[dim])

    rows = tensor.numel() // int(tensor.shape[-1])
    return tensor.as_strided((rows, int(tensor.shape[-1])), (row_stride, 1))


def is_cute_jit_enabled() -> bool:
    """True if the dev-time CuTe JIT-on-miss path should run.

    Reads `KESTREL_CUTE_JIT` first, then the legacy `KESTREL_CUTE_MOE_JIT`
    (with a one-time deprecation warning) so older scripts keep working
    while the new name propagates.
    """
    if os.environ.get("KESTREL_CUTE_JIT") == "1":
        return True
    if os.environ.get("KESTREL_CUTE_MOE_JIT") == "1":
        warn_fallback_once(
            "kestrel_cute_moe_jit_deprecated",
            "KESTREL_CUTE_MOE_JIT is deprecated; use KESTREL_CUTE_JIT instead. "
            "The legacy name will be removed in a future release.",
        )
        return True
    return False


def warn_fallback_once(kernel_key: str, message: str) -> None:
    with _FALLBACK_WARN_LOCK:
        if kernel_key in _FALLBACK_WARNED:
            return
        _FALLBACK_WARNED.add(kernel_key)
    warnings.warn(message, RuntimeWarning, stacklevel=2)


def device_capability(device: torch.device) -> tuple[int, int]:
    """Return (major, minor) capability for a CUDA device, else (0, 0)."""
    if device.type != "cuda":
        return (0, 0)
    index = int(torch.cuda.current_device() if device.index is None else device.index)
    return get_cuda_compute_capability(index)


def warn_and_run_fallback(
    *,
    kernel_key: str,
    message: str,
    fallback: Callable[..., _T],
    args: tuple[Any, ...] = (),
    kwargs: dict[str, Any] | None = None,
) -> _T:
    warn_fallback_once(kernel_key, message)
    if kwargs is None:
        kwargs = {}
    return fallback(*args, **kwargs)


def should_use_cuda_impl(
    *,
    device: torch.device,
    kernel_key: str,
    op_name: str,
    supported_sms: Iterable[int],
) -> bool:
    """Return True when CUDA impl is supported on `device`, else warn once and return False."""
    major, minor = device_capability(device)
    sm = major * 10 + minor
    allowed = sorted({int(v) for v in supported_sms})
    if sm in allowed:
        return True
    warn_fallback_once(
        kernel_key,
        "kestrel-kernels: falling back to PyTorch for "
        f"{op_name} (arch=sm{major}{minor}, supported_sms={allowed}).",
    )
    return False
